{
  "name": "opencode-plugin-updates",
  "version": "1.2.0",
  "type": "module",
  "description": "OpenCode plugin that checks installed plugins against npm and updates stale @latest caches",
  "author": "arttttt <artembambalov1993@gmail.com>",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/arttttt/opencode-plugin-updates.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "updates",
    "npm",
    "cache"
  ],
  "main": "src/entry/legacy.ts",
  "exports": {
    ".": "./src/entry/legacy.ts",
    "./server": "./src/entry/server.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@npmcli/config": "^10.14.0",
    "@opencode-ai/plugin": "^1.0.143",
    "@opencode-ai/sdk": "^1.0.143"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "@types/node": "^22.0.0",
    "bun": "^1.2.0",
    "typescript": "~5.9.3"
  },
  "engines": {
    "bun": ">=1.0.0",
    "opencode": "^1.2.0"
  }
}
